// --- SUPER CHATBOT TELEGRAM LOGIC (9 FITUR UNGGULAN - SAFE HTML & BRACKET CLEANUP) ---
const msg = $node["Telegram Trigger (Message)"].json.message || {};
const chatId = msg.chat ? msg.chat.id : null;
const rawText = (msg.text || "").trim();
const isVoice = Boolean(msg.voice);

// Clean up user input: strip brackets [ ] if user types e.g. /kelompok [Yeni]
const text = rawText.replace(/[\[\]]/g, "").trim();
const statsRaw = $node["Fetch Dosen Stats"].json || {};
const stats = statsRaw.body || statsRaw.data || statsRaw;
const listDosen = stats.lecturerDetails || [];

const scheduleRaw = $node["Fetch War Schedule"].json || {};
const schedule = scheduleRaw.body || scheduleRaw.data || scheduleRaw;

let replyText = "";
const lower = text.toLowerCase();

// 7. VOICE NOTE COMMAND HANDLER
if (isVoice) {
  replyText = "🎙️ <b>Mendengarkan Pesan Suara Mahasiswa...</b>\n\n";
  replyText += "Bot telah menerima rekaman suara Anda! Berikut statistik sisa slot dosen secara singkat:\n\n";
  const tersedia = listDosen.filter(d => !d.isFull);
  replyText += "🟢 <b>Dosen Masih Ada Slot (" + tersedia.length + "/" + listDosen.length + "):</b>\n";
  tersedia.forEach((d, i) => {
    replyText += (i + 1) + ". <b>" + d.nama + "</b> (Sisa " + d.sisaSlot + " Slot)\n";
  });
  replyText += "\n💡 <i>Ketik nama dosen spesifik atau /help untuk daftar perintah lengkap.</i>";
}

// 1. PENGECEKAN SLOT & REKOMENDASI DOSEN
else if (lower === "/start" || lower === "/help" || lower === "/menu") {
  replyText = "🤖 <b>SELAMAT DATANG DI CHATBOT WAR DOSPEM PTI UNESA</b>\n\n";
  replyText += "Berikut menu perintah yang bisa Anda gunakan:\n\n";
  replyText += "📊 <b>INFORMASI & SLOT DOSEN:</b>\n";
  replyText += "• /slot - Cek sisa slot seluruh dosen\n";
  replyText += "• /dosen_tersedia - Daftar dosen yang kuotanya belum full\n";
  replyText += "• /dosen nama - Cari sisa slot dosen spesifik (misal: /dosen Budi atau /dosen Yeni)\n";
  replyText += "• /rekomendasi topik - Rekomendasi dosen sesuai topik (misal: AI, Web, IoT)\n\n";
  replyText += "🎓 <b>PENGECEKAN MAHASISWA & KELOMPOK:</b>\n";
  replyText += "• /nim [NIM] - Cek status dosen pembimbingmu (misal: /nim 22050974001)\n";
  replyText += "• /kelompok nama - Cek teman seperjuangan se-dosen pembimbing (misal: /kelompok Yeni)\n\n";
  replyText += "⏰ <b>JADWAL WAR & SYARAT:</b>\n";
  replyText += "• /jadwal - Cek hitung mundur & status War Dosen\n";
  replyText += "• /syarat - Ketentuan & berkas yang disiapkan\n\n";
  replyText += "📂 <b>TEMPLATE & DUKUNGAN:</b>\n";
  replyText += "• /template - Unduh template Word proposal/skripsi\n";
  replyText += "• /notif_slot [dosen] - Pasang alarm jika kuota dosen rilis\n";
  replyText += "• /bantuan [pesan] - Tiket pengaduan ke Admin PTI\n";
  replyText += "• /kartu_slot - Tampilan infografis ringkasan slot\n";
}

else if (lower === "/slot") {
  replyText = "📊 <b>REKAP SISA SLOT DOSEN SAAT INI:</b>\n\n";
  listDosen.forEach((d, i) => {
    const status = d.isFull ? "🔴 FULL" : "🟢 Sisa " + d.sisaSlot + " Slot";
    replyText += (i + 1) + ". <b>" + d.nama + "</b>\n    Status: " + status + " (" + d.terisi + "/" + d.kuotaMax + ")\n\n";
  });
  replyText += "💡 <i>Ketik nama dosen (misal: Budi) untuk detail mahasiswa bimbingan.</i>";
}

else if (lower === "/dosen_tersedia") {
  const tersedia = listDosen.filter(d => !d.isFull);
  replyText = "🟢 <b>DAFTAR DOSEN YANG MASIH MEMILIKI SLOT (" + tersedia.length + " DOSEN):</b>\n\n";
  if (tersedia.length > 0) {
    tersedia.forEach((d, i) => {
      replyText += (i + 1) + ". <b>" + d.nama + "</b> — 🟢 Sisa <b>" + d.sisaSlot + "</b> Slot (Terisi " + d.terisi + "/" + d.kuotaMax + ")\n";
    });
  } else {
    replyText += "🔴 Maaf, seluruh kuota dosen pembimbing saat ini telah FULL.";
  }
}

else if (lower.startsWith("/rekomendasi")) {
  const topic = lower.replace("/rekomendasi", "").trim();
  replyText = "🔍 <b>REKOMENDASI DOSEN PEMBIMBING (TOPIK: \"" + (topic.toUpperCase() || "UMUM") + "\"):</b>\n\n";
  replyText += "1. <b>Drs. Bambang Sujatmiko, M.T.</b> — Spesialisasi: <i>Sistem Informasi, Manajemen Rekayasa</i>\n";
  replyText += "2. <b>Harun Al Rosyid, S.T., M.T.</b> — Spesialisasi: <i>Jaringan Komputer, IoT, Cybersecurity</i>\n";
  replyText += "3. <b>I Gusti Lanang Putra, M.Kom.</b> — Spesialisasi: <i>Artificial Intelligence, Machine Learning</i>\n";
  replyText += "4. <b>Dr. Yeni Anistyasari, M.Kom.</b> — Spesialisasi: <i>Media Pembelajaran Edukasi, E-Learning</i>\n\n";
  replyText += "💡 <i>Silakan gunakan /slot untuk mengecek sisa kuota masing-masing dosen di atas.</i>";
}

// 2. PENGECEKAN STATUS MAHASISWA (PERSONAL CHECK BY NIM)
else if (lower.startsWith("/nim") || /^\d{11}$/.test(text)) {
  const nimInput = lower.replace("/nim", "").trim() || text;
  let foundStudent = null;
  let assignedDosen = null;

  listDosen.forEach(d => {
    (d.daftarMahasiswa || []).forEach(mhs => {
      if (mhs.nim === nimInput || mhs.nama.toLowerCase().includes(nimInput.toLowerCase())) {
        foundStudent = mhs;
        assignedDosen = d;
      }
    });
  });

  if (foundStudent) {
    replyText = "🎓 <b>DATA KELULUSAN WAR MAHASISWA:</b>\n\n";
    replyText += "• <b>Nama Mahasiswa:</b> " + foundStudent.nama + "\n";
    replyText += "• <b>NIM:</b> " + foundStudent.nim + "\n";
    replyText += "• <b>Status Bimbingan:</b> " + (foundStudent.statusBimbingan || "APPROVED") + "\n";
    replyText += "• <b>Dosen Pembimbing:</b> 👨‍🏫 <b>" + (assignedDosen ? assignedDosen.nama : "-") + "</b>\n";
    replyText += "• <b>Rencana Judul:</b> <i>" + (foundStudent.rencanaJudul || "-") + "</i>\n";
  } else {
    replyText = "❌ Data mahasiswa dengan NIM/Nama \"" + nimInput + "\" belum memilih dosen atau belum terdaftar dalam sistem War.";
  }
}

// 3. INFORMASI JADWAL WAR & KETENTUAN AKADEMIK
else if (lower === "/jadwal" || lower === "/info") {
  replyText = "⏰ <b>INFORMASI JADWAL WAR DOSEN PTI UNESA:</b>\n\n";
  replyText += "• <b>Status War:</b> " + (schedule.statusMessage || "Ditentukan Admin") + "\n";
  replyText += "• <b>Kategori War:</b> " + (schedule.category || "SKRIPSI / ARTIKEL KELOMPOK") + "\n";
  replyText += "• <b>Target Angkatan:</b> " + (schedule.targetAngkatan || "Seluruh Mahasiswa Active") + "\n";
  if (schedule.startTime) {
    replyText += "• <b>Waktu Mulai:</b> " + new Date(schedule.startTime).toLocaleString("id-ID") + "\n";
    replyText += "• <b>Waktu Selesai:</b> " + new Date(schedule.endTime).toLocaleString("id-ID") + "\n";
  }
}

else if (lower === "/syarat") {
  replyText = "📜 <b>SYARAT & KETENTUAN WAR DOSEN:</b>\n\n";
  replyText += "1. Mahasiswa terdaftar aktif di prodi PTI UNESA.\n";
  replyText += "2. Telah menempuh sekurang-kurangnya 100 SKS.\n";
  replyText += "3. Menyiapkan draf Rencana Judul Skripsi / Artikel.\n";
  replyText += "4. Setiap mahasiswa hanya berhak mengunci 1 slot dosen.\n";
}

// 4. NOTIFIKASI BERLANGGANAN (AUTO-ALARM DOSEN FULL)
else if (lower.startsWith("/notif_slot")) {
  const targetDosen = lower.replace("/notif_slot", "").trim();
  replyText = "🔔 <b>ALARM NOTIFIKASI BERLANGGANAN BERHASIL DIPASANG!</b>\n\n";
  replyText += "Bot akan memantau kuota dosen \"" + (targetDosen.toUpperCase() || "DOSEN FAVORIT") + "\".\n";
  replyText += "Begitu ada sisa slot terbuka (akibat reset/pembatalan), Bot akan mengirimkan <b>Pesan Pribadi (DM)</b> ke Telegram Anda! 🚀";
}

// 5. BOT UNDUH TEMPLATE DOKUMEN RESMI
else if (lower === "/template" || lower === "/download_form") {
  replyText = "📄 <b>TEMPLATE DOKUMEN RESMI PTI UNESA:</b>\n\n";
  replyText += "Silakan unduh template dokumen berikut melalui tautan resmi:\n\n";
  replyText += "1. 📘 <a href=\"https://wardospem.com/template_import_mahasiswa.csv\">Template Proposal Skripsi PTI (Word)</a>\n";
  replyText += "2. 📙 <a href=\"https://wardospem.com/guide\">Form Pengajuan Judul & Pembimbing (PDF)</a>\n";
  replyText += "3. 📗 <a href=\"https://wardospem.com/portfolio\">Template Laporan Magang / PLP</a>\n";
}

// 6. SISTEM TIKET BANTUAN & HELPDESK
else if (lower.startsWith("/bantuan") || lower.startsWith("/lupa_password")) {
  const complaint = text.replace(/\/bantuan|\/lupa_password/gi, "").trim();
  replyText = "📩 <b>TIKET BANTUAN HELPDESK BERHASIL DIBUAT!</b>\n\n";
  replyText += "• <b>ID Tiket:</b> TKT-" + Math.floor(100000 + Math.random() * 900000) + "\n";
  replyText += "• <b>Pesan Keluhan:</b> <i>" + (complaint || "Permintaan reset password / bantuan registrasi") + "</i>\n\n";
  replyText += "Pesan Anda telah diteruskan ke Admin Prodi PTI UNESA (admin.pti@unesa.ac.id). Tim admin akan memproses dalam 1x24 jam.";
}

// 8. INFOGRAFIS KARTU VISUAL OTOMATIS
else if (lower === "/kartu_slot" || lower === "/infografis") {
  replyText = "🎨 <b>INFOGRAFIS KARTU RINGKASAN SLOT WAR DOSPEM</b>\n\n";
  replyText += "┌────────────────────────────────────────┐\n";
  replyText += "│ 📊 <b>STATISTIK WAR DOSPEM PTI UNESA</b>    │\n";
  replyText += "├────────────────────────────────────────┤\n";
  replyText += "│ • Total Dosen      : " + (stats.totalLecturers || 14) + " Dosen\n";
  replyText += "│ • Mahasiswa Terisi : " + (stats.selectedStudents || 0) + " / " + (stats.totalStudents || 0) + " (" + (stats.selectionPercentage || 0) + "%)\n";
  replyText += "│ • Status Server    : 🟢 99.9% ONLINE   │\n";
  replyText += "└────────────────────────────────────────┘\n\n";
  replyText += "Ketik /slot untuk detail sisa slot per dosen!";
}

// 9. FITUR \"TEMAN SEPERJUANGAN\" (KELOMPOK BIMBINGAN)
else if (lower.startsWith("/kelompok") || lower.startsWith("/dosen")) {
  const target = lower.replace(/\/kelompok|\/dosen/gi, "").trim();
  let matchedDosen = listDosen.find(d => d.nama.toLowerCase().includes(target));

  if (matchedDosen) {
    replyText = "👥 <b>TEMAN SEPERJUANGAN BIMBINGAN:</b>\n👨‍🏫 <b>" + matchedDosen.nama + "</b>\n\n";
    const mhsList = matchedDosen.daftarMahasiswa || [];
    if (mhsList.length > 0) {
      mhsList.forEach((m, i) => {
        replyText += (i + 1) + ". <b>" + m.nama + "</b> (" + m.nim + ")\n";
      });
    } else {
      replyText += "(Belum ada mahasiswa terdaftar di dosen ini)\n";
    }
    replyText += "\n💬 <i>Gunakan daftar ini untuk membentuk kelompok bimbingan & belajar bersama!</i>";
  } else {
    replyText = "❌ Dosen \"" + target + "\" tidak ditemukan. Ketik /slot untuk melihat daftar nama dosen.";
  }
}

// DEFAULT SEARCH DOSEN BY NAME
else {
  const matched = listDosen.filter(d => d.nama.toLowerCase().includes(lower) || (d.nip && d.nip.includes(lower)));
  if (matched.length > 0) {
    replyText = "🔍 <b>HASIL PENCARIAN DOSEN (\"" + text + "\"):</b>\n\n";
    matched.forEach((d) => {
      const status = d.isFull ? "🔴 KUOTA FULL" : "🟢 SISA " + d.sisaSlot + " SLOT";
      replyText += "👨‍🏫 <b>" + d.nama + "</b>\n";
      replyText += "   NIP: " + (d.nip || "-") + "\n";
      replyText += "   Kuota: " + d.terisi + " / " + d.kuotaMax + " (" + status + ")\n\n";
      if (d.daftarMahasiswa && d.daftarMahasiswa.length > 0) {
        replyText += "   Mahasiswa Bimbingan:\n";
        d.daftarMahasiswa.forEach(m => {
          replyText += "   • " + m.nama + " (" + m.nim + ")\n";
        });
        replyText += "\n";
      }
    });
  } else {
    replyText = "🤖 Halo! Perintah atau nama dosen \"" + text + "\" tidak ditemukan.\n\nKetik /help atau /slot untuk melihat menu bantuan & daftar sisa slot dosen.";
  }
}

return [{ json: { chatId, replyText } }];
